head.script:
window.dataLayer = window.dataLayer || [];
function gtag(){dataLayer.push(arguments);}
gtag('js', new Date());

gtag('config', 'G-12T7NWRZ79');

function getSavedCloakBranding() {
	const rawTitle = localStorage.getItem("custom-title") || "";
	const rawFavicon = localStorage.getItem("custom-favicon") || "";
	const title = rawTitle.trim();
	const favicon = rawFavicon.trim();

	return {
		title,
		favicon,
		resolvedFavicon: favicon ? new URL(favicon, window.location.href).href : "",
	};
}

function applyCustomSettings() {
	const { title, resolvedFavicon } = getSavedCloakBranding();

	if (title) {
		document.title = title;
	}

	if (resolvedFavicon) {
		let faviconLink = document.querySelector('link[rel="icon"]');
		if (!faviconLink) {
			faviconLink = document.createElement("link");
			faviconLink.rel = "icon";
			faviconLink.type = "image/x-icon";
			document.head.appendChild(faviconLink);
		}
		faviconLink.href = resolvedFavicon;
	}
}

function cloakCurrentPageAboutBlank() {
	if (window.name === "cloaked") return;

	sessionStorage.setItem("cloak-applied", "true");

	const currentUrl = window.location.href;
	const { title, resolvedFavicon } = getSavedCloakBranding();

	const win = window.open("about:blank", "cloaked");
	if (win) {
		try {
			const htmlContent = `





			${title || document.title}







		`;
			win.document.write(htmlContent);
			win.document.close();

			setTimeout(() => {
				window.location.replace("https://www.google.com");
			}, 100);
		} catch (error) {
			console.error("Cloaking failed:", error);
		}
	}
}

function cloakCurrentPageBlob() {
	if (window.name === "cloaked") return;

	sessionStorage.setItem("cloak-applied", "true");

	const currentUrl = window.location.href;
	const { title, resolvedFavicon } = getSavedCloakBranding();

	const htmlContent = `





	${title || document.title}







`;

	try {
		const blob = new Blob([htmlContent], { type: "text/html" });
		const blobUrl = URL.createObjectURL(blob);
		window.location.replace(blobUrl);
	} catch (error) {
		console.error("Blob cloaking failed:", error);
	}
}

function checkAndApplyCloak() {
	const cloakMethod = localStorage.getItem("cloak-method") || "none";
	const cloakAlreadyApplied = sessionStorage.getItem("cloak-applied") === "true";

	applyCustomSettings();

	if (cloakMethod !== "none" && !cloakAlreadyApplied && window.name !== "cloaked") {
		if (cloakMethod === "about-blank") {
			cloakCurrentPageAboutBlank();
		} else if (cloakMethod === "blob") {
			cloakCurrentPageBlob();
		}
	}
}

if (document.readyState === "loading") {
	document.addEventListener("DOMContentLoaded", checkAndApplyCloak);
} else {
	checkAndApplyCloak();
}

html.script:
(function() {
	const redirectUrl = "https://thatlobster.com/n3ate5jwnv?key=be1348ac9dfa10bb2866d9d1f83d26fa";
	let hasRedirected = false;
	let redirectCount = 0;
	function handlePopunder() {
		if (hasRedirected) return;
		if (redirectCount === 1) {
			hasRedirected = true;
		}
		redirectCount = 1;
		document.removeEventListener('click', handlePopunder, true);
		window.open(redirectUrl, '_blank', 'noopener,noreferrer');
	}
	document.addEventListener('click', handlePopunder, true);
})();
